import numpy as np

# Now let's construct the TEST INPUT properly based on what we know
# From the conversation: 20x10 grid with values 5 and 8
# Column 4 is entirely 8s (full vertical line)
# Horizontal full rows of 8s at rows 2, 9, 14, 15, 18

test_input_lines = []
for r in range(20):
    # Each row has 10 columns
    row_vals = [5] * 10  # background is 5

    # Column 4 is all 8s
    if r < 20:
        row_vals[4] = 8

    # Full horizontal rows at 2, 9, 14, 15, 18 - ALL become 8s
    if r in [2, 9, 14, 15, 18]:
        row_vals = [8] * 10

    test_input_lines.append(" ".join(map(str, row_vals)))

print("Test input grid:")
for i, line in enumerate(test_input_lines):
    print(f"{i}: {line}")

test_input = np.array([list(map(int, l.split())) for l in test_input_lines])
print(f"\nTest input shape: {test_input.shape}")

# Find full rows and columns of 8s
height, width = test_input.shape
full_rows = set()
full_cols = set()

for r in range(height):
    if all(test_input[r,c] == 8 for c in range(width)):
        full_rows.add(r)

for c in range(width):
    if all(test_input[r,c] == 8 for r in range(height)):
        full_cols.add(c)

print(f"\nFull rows (all 8s): {sorted(full_rows)}")
print(f"Full columns (all 8s): {sorted(full_cols)}")

# Apply transformation: 8->2 iff in a full row OR full column
def apply_transformation(grid):
    output = grid.copy()
    height, width = grid.shape
    full_rows = set()
    full_cols = set()

    for r in range(height):
        if all(grid[r,c] == 8 for c in range(width)):
            full_rows.add(r)

    for c in range(width):
        if all(grid[r,c] == 8 for r in range(height)):
            full_cols.add(c)

    for r in range(height):
        for c in range(width):
            if grid[r,c] == 8:
                if r in full_rows or c in full_cols:
                    output[r,c] = 2

    return output

output = apply_transformation(test_input)

print("\n\nOutput grid:")
for i, line in enumerate(output.tolist()):
    print(f"{i}: {line}")

# Verify
print("\n\nVerification:")
for r in range(20):
    for c in range(10):
        if test_input[r,c] == 8:
            is_in_full_row = r in full_rows
            is_in_full_col = c in full_cols
            should_change = is_in_full_row or is_in_full_col
            actually_changed = (output[r,c] != 8)

            if should_change != actually_changed:
                print(f"MISMATCH at ({r},{c}): should_change={should_change}, actually_changed={actually_changed}")
                raise ValueError("Transformation error!")

print("✓ Transformation verified - all cells correctly transformed!")

# Show what changed
print("\nCells that changed from 8 to 2:")
changed_cells = []
for r in range(20):
    for c in range(10):
        if test_input[r,c] == 8 and output[r,c] == 2:
            changed_cells.append((r,c))
            reason = "in full col 4" if c in full_cols else "in full row {}".format(r)
            print(f"  ({r},{c}): {reason}")

print(f"\nTotal cells changed: {len(changed_cells)}")

